style.css:
body {
  margin: 0;
  padding: 0;
  background-image: url('https://i.pinimg.com/736x/4c/b8/4c/4cb84c6e64079385226686633263663d.jpg');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-attachment: fixed; /* so it scrolls with the page */
  font-family: 'Helvetica Neue', sans-serif;
  color: #fff; /* Optional: makes sure text doesn't vanish on dark bg */
}
